"""Every ribbon group has the same caption style and outer margins (hst-ribbon-caption-style.patch, generated by
scripts/patches/normalise-ribbon-captions.py). Reads the patch and runs the generator on a small fixture."""
import importlib.util
import os
import unittest

from _paths import ROOT
from test_ribbon_group_button import sections

PATCHES = os.path.join(ROOT, "patches", "libreoffice")
PATCH = os.path.join(PATCHES, "hst-ribbon-caption-style.patch")
spec = importlib.util.spec_from_file_location("normalise_ribbon_captions",
                                              os.path.join(ROOT, "scripts/patches/normalise-ribbon-captions.py"))
gen = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gen)

FIXTURE = """<?xml version="1.0" encoding="UTF-8"?>
<interface>
  <object class="sfxlo-PriorityMergedHBox" id="box">
    <child>
      <object class="GtkGrid" id="gdOne">
        <property name="visible">True</property>
        <property name="can-focus">False</property>
        <property name="margin-start">3</property>
        <property name="margin-end">6</property>
        <property name="row-spacing">3</property>
        <child>
          <object class="GtkLabel" id="lbOne">
            <property name="label">One</property>
            <attributes>
              <attribute name="style" value="italic"/>
              <attribute name="scale" value="0.9"/>
              <attribute name="weight" value="thin"/>
            </attributes>
          </object>
          <packing>
            <property name="left-attach">0</property>
            <property name="top-attach">2</property>
          </packing>
        </child>
        <child>
          <object class="GtkLabel" id="lbContent">
            <property name="label">Content</property>
            <attributes>
              <attribute name="style" value="italic"/>
            </attributes>
          </object>
          <packing>
            <property name="left-attach">0</property>
            <property name="top-attach">0</property>
          </packing>
        </child>
      </object>
    </child>
  </object>
  <object class="GtkGrid" id="gdOutside">
    <property name="margin-start">9</property>
  </object>
</interface>
"""


class CaptionStyle(unittest.TestCase):
    def test_generator_normalises_groups_only(self):
        out = gen.normalise(FIXTURE)
        start = out.index('id="gdOne"')
        grid = out[start:out.index("<child>", start)]
        for name, value in gen.MARGINS:
            self.assertIn(f'<property name="{name}">{value}</property>', grid)
        self.assertIn('<property name="row-spacing">3</property>', grid)  # spacing inside stays
        caption = out[out.index('id="lbOne"'):out.index('id="lbContent"')]
        self.assertIn('<attribute name="style" value="normal"/>', caption)
        self.assertNotIn("italic", caption)
        self.assertNotIn("thin", caption)
        # a label that is not the caption (not in the last row) and a grid outside the boxes are untouched
        self.assertIn('<attribute name="style" value="italic"/>', out[out.index('id="lbContent"'):])
        self.assertIn('<property name="margin-start">9</property>', out)
        self.assertEqual(gen.normalise(out), out)  # idempotent

    def test_patch_only_sets_caption_style_and_margins(self):
        found = sections(PATCH)
        self.assertEqual(sorted(found), sorted(gen.UI))  # Writer, Sheets, Slides; not Draw
        allowed = {f'<property name="{n}">{v}</property>' for n, v in gen.MARGINS}
        allowed |= {f'<attribute name="{n}" value="{v}"/>' for n, v in gen.CAPTION_ATTRIBUTES}
        for path, (added, _removed, _text) in found.items():
            for line in added:
                self.assertIn(line.strip(), allowed, path)

    def test_in_series_after_the_group_gaps_patch(self):
        with open(os.path.join(PATCHES, "series"), encoding="utf-8") as handle:
            names = [line.strip() for line in handle if line.strip() and not line.startswith("#")]
        self.assertLess(names.index("hst-ribbon-group-gaps.patch"), names.index("hst-ribbon-caption-style.patch"))


if __name__ == "__main__":
    unittest.main()
